16	package org.springframework.samples.petclinic.rest;
17	
18	import java.util.Collection;
19	import java.util.HashSet;
20	import java.util.Set;
21	
22	import org.springframework.samples.petclinic.util.LocalityResolver;
23	import org.springframework.samples.petclinic.util.Sha256Hex;
24	import org.springframework.stereotype.Component;
25	
26	/**
27	 * Builds an owner's customer code, formatted {@code '<REGION>-<HASH8>'} where {@code REGION}
28	 * is the region code derived from the postcode and {@code HASH8} the first 8 upper-case hex
29	 * characters of SHA-256 over the normalized telephone concatenated with the last name,
30	 * e.g. {@code 'NSW-3F2A9C1E'}.
31	 */
32	@Component
33	public class CustomerCodeGenerator {
34	
35	    /** Separator between the region and hash segments of a customer code. */
36	    private static final char SEPARATOR = '-';
37	
38	    /** Number of hex characters taken from the SHA-256 digest for the hash segment. */
39	    private static final int HASH_LENGTH = 8;
40	
41	    /**
42	     * Generate a customer code for a new owner.
43	     *
44	     * @param region    the region code derived from the owner's postcode; forms the prefix
45	     * @param telephone the owner's normalized telephone; hashed with the last name to form the suffix
