295	    /**
296	     * Computes the customer code for an owner about to be created, de-duplicated against the codes
297	     * already assigned to existing owners so that distinct owners always receive distinct codes.
298	     *
299	     * @return the owner's unique customer code
300	     */
301	    private String assignCustomerCode(Owner owner) {
302	        String region = LocalityResolver.localityOf(owner.getPostcode(), owner.getCity());
303	        String baseCode = customerCodeGenerator.generate(
304	            region, owner.getTelephone(), owner.getLastName());
305	        List<String> takenCodes = clinicService.findOwnersByCustomerCodeStartingWith(baseCode)
306	            .stream()
307	            .map(Owner::getCustomerCode)
308	            .toList();
