18	import org.springframework.context.annotation.Profile;
19	import org.springframework.dao.DataAccessException;
20	import org.springframework.dao.EmptyResultDataAccessException;
21	import org.springframework.data.domain.Page;
22	import org.springframework.data.domain.PageImpl;
23	import org.springframework.data.domain.Pageable;
24	import org.springframework.jdbc.core.BeanPropertyRowMapper;
25	import org.springframework.jdbc.core.namedparam.BeanPropertySqlParameterSource;
26	import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
27	import org.springframework.jdbc.core.simple.SimpleJdbcInsert;
28	import org.springframework.orm.ObjectRetrievalFailureException;
29	import org.springframework.samples.petclinic.model.Owner;
30	import org.springframework.samples.petclinic.model.Pet;
31	import org.springframework.samples.petclinic.model.PetType;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.repository.OwnerRepository;
34	import org.springframework.samples.petclinic.util.EntityUtils;
35	import org.springframework.stereotype.Repository;
36	
37	import javax.sql.DataSource;
38	import jakarta.transaction.Transactional;
39	import java.util.Collection;
40	import java.util.HashMap;
41	import java.util.List;
42	import java.util.Map;
43	
44	/**
45	 * A simple JDBC-based implementation of the {@link OwnerRepository} interface.
46	 *
47	 * @author Ken Krebs
48	 * @author Juergen Hoeller
49	 * @author Rob Harrop
50	 * @author Sam Brannen
51	 * @author Thomas Risberg
52	 * @author Mark Fisher
53	 * @author Antoine Rey
54	 * @author Vitaliy Fedoriv
55	 */
56	@DependsOnDatabaseInitialization
57	@Repository
58	@Profile("jdbc")
59	public class JdbcOwnerRepositoryImpl implements OwnerRepository {
60	
61	    private NamedParameterJdbcTemplate namedParameterJdbcTemplate;
62	
63	    private SimpleJdbcInsert insertOwner;
64	
65	    public JdbcOwnerRepositoryImpl(DataSource dataSource) {
66	
67	        this.insertOwner = new SimpleJdbcInsert(dataSource)
68	            .withTableName("owners")
69	            .usingGeneratedKeyColumns("id");
70	
71	        this.namedParameterJdbcTemplate = new NamedParameterJdbcTemplate(dataSource);
72	
73	    }
74	
75	
76	    /**
77	     * Loads {@link Owner Owners} from the data store by last name, returning all owners whose last name <i>starts</i> with
78	     * the given name; also loads the {@link Pet Pets} and {@link Visit Visits} for the corresponding owners, if not
79	     * already loaded.
80	     */
81	    @Override
82	    public Collection<Owner> findByLastName(String lastName) throws DataAccessException {
83	        Map<String, Object> params = new HashMap<>();
84	        params.put("lastName", lastName + "%");
85	        List<Owner> owners = this.namedParameterJdbcTemplate.query(
86	            "SELECT id, first_name, last_name, address, city, telephone, email FROM owners WHERE last_name like :lastName",
87	            params,
88	            BeanPropertyRowMapper.newInstance(Owner.class)
89	        );
90	        loadOwnersPetsAndVisits(owners);
91	        return owners;
92	    }
93	
94	    @Override
95	    public Page<Owner> findByLastName(String lastName, Pageable pageable) throws DataAccessException {
96	        Map<String, Object> params = new HashMap<>();
97	        params.put("lastName", lastName + "%");
98	        params.put("size", pageable.getPageSize());
99	        params.put("offset", pageable.getOffset());
100	        List<Owner> owners = this.namedParameterJdbcTemplate.query(
101	            "SELECT id, first_name, last_name, address, city, telephone, email FROM owners WHERE last_name like :lastName ORDER BY id LIMIT :size OFFSET :offset",
102	            params,
103	            BeanPropertyRowMapper.newInstance(Owner.class)
104	        );
105	        loadOwnersPetsAndVisits(owners);
106	        Long total = this.namedParameterJdbcTemplate.queryForObject(
107	            "SELECT COUNT(*) FROM owners WHERE last_name like :lastName",
108	            params,
109	            Long.class
110	        );
111	        return new PageImpl<>(owners, pageable, total == null ? 0 : total);
112	    }
113	
114	    /**
115	     * Loads the {@link Owner} with the supplied <code>id</code>; also loads the {@link Pet Pets} and {@link Visit Visits}
116	     * for the corresponding owner, if not already loaded.
117	     */
118	    @Override
119	    public Owner findById(int id) throws DataAccessException {
120	        Owner owner;
121	        try {
122	            Map<String, Object> params = new HashMap<>();
123	            params.put("id", id);
124	            owner = this.namedParameterJdbcTemplate.queryForObject(
125	                "SELECT id, first_name, last_name, address, city, telephone, email FROM owners WHERE id= :id",
126	                params,
127	                BeanPropertyRowMapper.newInstance(Owner.class)
128	            );
129	        } catch (EmptyResultDataAccessException ex) {
130	            throw new ObjectRetrievalFailureException(Owner.class, id);
131	        }
132	        loadPetsAndVisits(owner);
133	        return owner;
134	    }
135	
136	    public void loadPetsAndVisits(final Owner owner) {
137	        Map<String, Object> params = new HashMap<>();
138	        params.put("id", owner.getId());
139	        final List<JdbcPet> pets = this.namedParameterJdbcTemplate.query(
140	            "SELECT pets.id as pets_id, name, birth_date, type_id, owner_id, visits.id as visit_id, visit_date, description, visits.pet_id as visits_pet_id FROM pets LEFT OUTER JOIN visits ON pets.id = visits.pet_id WHERE owner_id=:id ORDER BY pets.id",
141	            params,
142	            new JdbcPetVisitExtractor()
143	        );
144	        Collection<PetType> petTypes = getPetTypes();
145	        for (JdbcPet pet : pets) {
146	            pet.setType(EntityUtils.getById(petTypes, PetType.class, pet.getTypeId()));
147	            owner.addPet(pet);
148	        }
149	    }
150	
151	    @Override
152	    public Collection<Owner> findByTelephone(String telephone) throws DataAccessException {
153	        Map<String, Object> params = new HashMap<>();
154	        params.put("telephone", telephone);
155	        List<Owner> owners = this.namedParameterJdbcTemplate.query(
156	            "SELECT id, first_name, last_name, address, city, telephone, email FROM owners WHERE telephone = :telephone",
157	            params,
158	            BeanPropertyRowMapper.newInstance(Owner.class)
159	        );
160	        loadOwnersPetsAndVisits(owners);
161	        return owners;
162	    }
163	
164	    @Override
165	    public Collection<Owner> findByLastNameIgnoreCase(String lastName) throws DataAccessException {
166	        Map<String, Object> params = new HashMap<>();
167	        params.put("lastName", lastName);
168	        List<Owner> owners = this.namedParameterJdbcTemplate.query(
169	            "SELECT id, first_name, last_name, address, city, telephone, email FROM owners WHERE LOWER(last_name) = LOWER(:lastName)",
170	            params,
171	            BeanPropertyRowMapper.newInstance(Owner.class)
172	        );
173	        loadOwnersPetsAndVisits(owners);
174	        return owners;
175	    }
176	
177	    @Override
178	    public Collection<Owner> findByEmailIgnoreCase(String email) throws DataAccessException {
179	        Map<String, Object> params = new HashMap<>();
180	        params.put("email", email);
181	        List<Owner> owners = this.namedParameterJdbcTemplate.query(
182	            "SELECT id, first_name, last_name, address, city, telephone, email FROM owners WHERE LOWER(email) = LOWER(:email)",
183	            params,
184	            BeanPropertyRowMapper.newInstance(Owner.class)
185	        );
186	        loadOwnersPetsAndVisits(owners);
187	        return owners;
188	    }
189	
190	    @Override
191	    public Collection<Owner> findByCustomerCodeStartingWith(String prefix) throws DataAccessException {
192	        Map<String, Object> params = new HashMap<>();
193	        params.put("prefix", prefix + "%");
194	        List<Owner> owners = this.namedParameterJdbcTemplate.query(
195	            "SELECT id, first_name, last_name, address, city, telephone, email, customer_code FROM owners WHERE customer_code LIKE :prefix",
196	            params,
197	            BeanPropertyRowMapper.newInstance(Owner.class)
198	        );
199	        loadOwnersPetsAndVisits(owners);
200	        return owners;
201	    }
202	
203	    @Override
204	    public void save(Owner owner) throws DataAccessException {
205	        BeanPropertySqlParameterSource parameterSource = new BeanPropertySqlParameterSource(owner);
206	        if (owner.isNew()) {
207	            Number newKey = this.insertOwner.executeAndReturnKey(parameterSource);
208	            owner.setId(newKey.intValue());
209	        } else {
210	            this.namedParameterJdbcTemplate.update(
211	                "UPDATE owners SET first_name=:firstName, last_name=:lastName, address=:address, " +
212	                    "city=:city, telephone=:telephone, email=:email WHERE id=:id",
213	                parameterSource);
214	        }
215	    }
216	
217	    public Collection<PetType> getPetTypes() throws DataAccessException {
218	        return this.namedParameterJdbcTemplate.query(
219	            "SELECT id, name FROM types ORDER BY name", new HashMap<String, Object>(),
220	            BeanPropertyRowMapper.newInstance(PetType.class));
221	    }
222	
223	    /**
224	     * Loads the {@link Pet} and {@link Visit} data for the supplied {@link List} of {@link Owner Owners}.
225	     *
226	     * @param owners the list of owners for whom the pet and visit data should be loaded
227	     * @see #loadPetsAndVisits(Owner)
228	     */
229	    private void loadOwnersPetsAndVisits(List<Owner> owners) {
230	        for (Owner owner : owners) {
231	            loadPetsAndVisits(owner);
232	        }
233	    }
234	
235		@Override
236		public Collection<Owner> findAll() throws DataAccessException {
237			List<Owner> owners = this.namedParameterJdbcTemplate.query(
238		            "SELECT id, first_name, last_name, address, city, telephone, email FROM owners",
239		            new HashMap<String, Object>(),
240		            BeanPropertyRowMapper.newInstance(Owner.class));
241			for (Owner owner : owners) {
242	            loadPetsAndVisits(owner);
243	        }
244		    return owners;
245		}
246	
247	    @Override
248	    public Page<Owner> findAll(Pageable pageable) throws DataAccessException {
249	        Map<String, Object> params = new HashMap<>();
250	        params.put("size", pageable.getPageSize());
251	        params.put("offset", pageable.getOffset());
252	        List<Owner> owners = this.namedParameterJdbcTemplate.query(
253	            "SELECT id, first_name, last_name, address, city, telephone, email FROM owners ORDER BY id LIMIT :size OFFSET :offset",
254	            params,
255	            BeanPropertyRowMapper.newInstance(Owner.class));
256	        loadOwnersPetsAndVisits(owners);
257	        Long total = this.namedParameterJdbcTemplate.queryForObject(
258	            "SELECT COUNT(*) FROM owners",
259	            params,
260	            Long.class
261	        );
262	        return new PageImpl<>(owners, pageable, total == null ? 0 : total);
263	    }
264	
265	    @Override
266	    public long count() throws DataAccessException {
267	        Long total = this.namedParameterJdbcTemplate.queryForObject(
268	            "SELECT COUNT(*) FROM owners",
269	            new HashMap<String, Object>(),
270	            Long.class
271	        );
272	        return total == null ? 0 : total;
273	    }
274	
275	    @Override
276	    public long countByCity(String city) throws DataAccessException {
277	        Map<String, Object> params = new HashMap<>();
278	        params.put("city", city);
279	        Long total = this.namedParameterJdbcTemplate.queryForObject(
280	            "SELECT COUNT(*) FROM owners WHERE LOWER(city) = LOWER(:city)",
281	            params,
282	            Long.class
283	        );
284	        return total == null ? 0 : total;
285	    }
286	
287	    @Override
288	    public long countByRegistrationDate(java.time.LocalDate registrationDate) throws DataAccessException {
289	        Map<String, Object> params = new HashMap<>();
290	        params.put("registrationDate", registrationDate);
291	        Long total = this.namedParameterJdbcTemplate.queryForObject(
292	            "SELECT COUNT(*) FROM owners WHERE registration_date = :registrationDate",
293	            params,
294	            Long.class
295	        );
296	        return total == null ? 0 : total;
297	    }
298	
299		@Override
300		@Transactional
301		public void delete(Owner owner) throws DataAccessException {
302			Map<String, Object> ownerParams = new HashMap<>();
303			ownerParams.put("id", owner.getId());
304	        List<Pet> pets = owner.getPets();
305	        // cascade delete pets
306	        for (Pet pet : pets){
307	        	Map<String, Object> petParams = new HashMap<>();
308	        	petParams.put("id", pet.getId());
309	        	// cascade delete visits
310	        	List<Visit> visits = pet.getVisits();
311	            for (Visit visit : visits){
312	            	Map<String, Object> visitParams = new HashMap<>();
313	            	visitParams.put("id", visit.getId());
314	            	this.namedParameterJdbcTemplate.update("DELETE FROM visits WHERE id=:id", visitParams);
315	            }
316	            this.namedParameterJdbcTemplate.update("DELETE FROM pets WHERE id=:id", petParams);
317	        }
318	        this.namedParameterJdbcTemplate.update("DELETE FROM owners WHERE id=:id", ownerParams);
319		}
320	
321	
322	}
